using System;using System.Linq;using System.Reflection;using System.Threading.Tasks;using UnityEngine;using AntColony.Core;using AntColony.Data;using AntColony.Buildings;using AntColony.Units;
public static class Motion1113Targets {
 public static async Task<string> Run(){AntColony.UI.SimulationPause.UserSpeed(0);var c=CommanderRoster.Instance.Commanders.First(x=>x&&x.IsColonyMember);c.CommandStop();var get=typeof(BuildingPlacementController).GetMethod("GetTemplate",BindingFlags.Static|BindingFlags.NonPublic|BindingFlags.Public);var template=(GameObject)get.Invoke(null,new object[]{BuildingKind.Farm,UnitRole.Worker});var pos=c.Position+Vector3.right*5;Physics.Raycast(pos+Vector3.up*10,Vector3.down,out var ground,30,1<<8);pos.y=ground.point.y;var go=UnityEngine.Object.Instantiate(template,pos,Quaternion.identity);go.name="MOTION1113 Farm";go.transform.position+=Vector3.up*(pos.y-go.GetComponent<Renderer>().bounds.min.y);go.SetActive(true);FacilityVisual.Attach(go.GetComponent<BuildingBase>());await Task.Delay(200);return string.Join("\n",go.GetComponentsInChildren<MeshRenderer>().Where(r=>r.enabled&&!r.forceRenderingOff).Select(r=>r.name+" y="+(r.bounds.min.y-pos.y)+".."+(r.bounds.max.y-pos.y)+" size="+r.bounds.size));}
}
